`validators.py`:

```
"""Validators over depot run outputs. Each ``VN`` subclasses ``Check`` from ``checks_base``.

Use as ``VN().run(items)``, which returns a ``CheckResult``. ``Check.run`` handles empty
input and "nothing measured" before the subclass is consulted; a crash in ``check`` is a fail.
"""
from checks_base import Check

# Notification types named in the depot spec (C14, C17, C20, C22, C13).
SPEC_NOTIFICATION_TYPES = (
    "AUDIT_MISMATCH",
    "REORDER",
    "EXPIRY",
    "SUPPLIER_SUSPENDED",
    "OVERDRAWN",
)


class V1(Check):
    """Every report row's value equals units * unit_cost."""

    name = "rows"

    def check(self, items):
        mismatches = []
        for row in items:
            if row["units"] * row["unit_cost"] != row["value_cents"]:
                mismatches.append(
                    {
                        "sku": row["sku"],
                        "wh": row["wh"],
                        "units": row["units"],
                        "unit_cost": row["unit_cost"],
                        "value_cents": row["value_cents"],
                    }
                )
        return (not mismatches), {"checked": len(items), "mismatches": mismatches}


class V2(Check):
    """Every notification type in the spec was seen across the runs."""

    name = "runs"
    required = SPEC_NOTIFICATION_TYPES

    def check(self, items):
        seen = set()
        for run in items:
            for notification in run:
                seen.add(notification[0])
        missing = [t for t in self.required if t not in seen]
        return (not missing), {"seen": sorted(seen), "missing": missing}


class V3(Check):
    """Two runs with the same seed are identical."""

    name = "pairs"

    def check(self, items):
        differing = []
        for pair in items:
            if pair["a"] != pair["b"]:
                differing.append(pair["seed"])
        return (not differing), {"pairs": len(items), "differing_seeds": differing}


class V4(Check):
    """Storage cost stayed within budget on every day."""

    name = "days"

    def check(self, items):
        over = []
        for day in items:
            if day["storage_cost_cents"] > day["budget_cents"]:
                over.append(
                    {
                        "day": day["day"],
                        "storage_cost_cents": day["storage_cost_cents"],
                        "budget_cents": day["budget_cents"],
                    }
                )
        return (not over), {"days": len(items), "over_budget": over}


class V5(Check):
    """Every clause has at least one test."""

    name = "clauses"

    def check(self, items):
        untested = []
        for entry in items:
            tests = [t for t in entry["tests"] if isinstance(t, str) and t.strip()]
            if not tests:
                untested.append(entry["clause_id"])
        return (not untested), {"clauses": len(items), "untested": untested}


class V6(Check):
    """Results from two implementations agree on every compared pair."""

    name = "pairs"

    def check(self, items):
        disagreements = []
        for pair in items:
            if not (pair["a"] == pair["b"]):
                disagreements.append({"key": pair["key"], "a": pair["a"], "b": pair["b"]})
        return (not disagreements), {"compared": len(items), "disagreements": disagreements}
```

`checks_base.py`:

```
"""The ``Check`` base class: a check never passes on nothing (brief 3, and E2's guard condition).

``Check.run(items)`` returns ``failed: empty input`` for empty or all-unmeasured input *before*
calling the subclass, and ``failed: nothing measured`` when the subclass measured nothing. The
harness's own checks (presence, reach, parity, mutation) subclass it, and so do the agent's
validators in E2's guard condition (the agent gets this file as ``checks_base.py``).

This file is standard-library only so it can be copied verbatim into the agent's repo.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class CheckResult:
    passed: bool
    measured: Any
    reason: str = ""

    def __iter__(self):  # allows ``passed, measured = check.run(x)``
        yield self.passed
        yield self.measured

    def __bool__(self) -> bool:
        return bool(self.passed)


def is_empty(value: Any) -> bool:
    """True for None, empty containers, and containers whose every leaf is None or empty."""
    if value is None:
        return True
    if isinstance(value, (str, bytes)):
        return len(value) == 0
    if isinstance(value, dict):
        return len(value) == 0 or all(is_empty(v) for v in value.values())
    if isinstance(value, (list, tuple, set, frozenset)):
        return len(value) == 0 or all(is_empty(v) for v in value)
    return False


class Check:
    """Subclasses implement ``check(items) -> (passed, measured)``; callers use ``run(items)``."""

    name = "check"

    def run(self, items: Any) -> CheckResult:
        if hasattr(items, "__next__"):  # a lazy source of runs: materialise before judging emptiness
            items = list(items)
        if is_empty(items):
            return CheckResult(False, None, "failed: empty input")
        try:
            passed, measured = self.check(items)
        except Exception as exc:  # a check that crashes has not passed
            return CheckResult(False, None, f"failed: {type(exc).__name__}: {exc}")
        if is_empty(measured):
            return CheckResult(False, measured, "failed: nothing measured")
        return CheckResult(bool(passed), measured, "" if passed else "failed")

    def check(self, items: Any) -> tuple[bool, Any]:  # pragma: no cover - abstract
        raise NotImplementedError
```

