I've added V7, V8 and V9 to a new `validators_later.py`, plus a `test_validators_later.py` because CONTRIBUTING requires tests with every change.

<file path="validators_later.py">
"""Later validators over depot run outputs. Each ``VN`` subclasses ``Check`` from ``checks_base``.

Use as ``VN().run(items)``, which returns a ``CheckResult``. ``Check.run`` handles empty
input and "nothing measured" before the subclass is consulted; a crash in ``check`` is a fail.
"""
from collections import Counter

from checks_base import Check

# Inclusive bounds for supplier reliability. The spec does not state them; 0-100 is assumed.
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


class V7(Check):
    """Every warehouse's capacity was respected across runs."""

    name = "entries"

    def check(self, items):
        over_capacity = []
        for entry in items:
            if entry["max_units"] > entry["capacity"]:
                over_capacity.append(
                    {
                        "wh": entry["wh"],
                        "capacity": entry["capacity"],
                        "max_units": entry["max_units"],
                    }
                )
        return (not over_capacity), {"warehouses": len(items), "over_capacity": over_capacity}


class V8(Check):
    """All expiries were notified. An expired [sku, wh, qty] needs a matching notified entry."""

    name = "entries"

    def check(self, items):
        unnotified = []
        for entry in items:
            expired = Counter(tuple(item) for item in entry["expired"])
            notified = Counter(tuple(item) for item in entry["notified"])
            for item, count in (expired - notified).items():
                unnotified.extend([list(item)] * count)
        return (not unnotified), {"entries": len(items), "unnotified": unnotified}


class V9(Check):
    """Every supplier's reliability stayed in range."""

    name = "entries"

    def check(self, items):
        out_of_range = []
        for entry in items:
            if not (RELIABILITY_MIN <= entry["reliability"] <= RELIABILITY_MAX):
                out_of_range.append(
                    {"supplier": entry["supplier"], "reliability": entry["reliability"]}
                )
        return (not out_of_range), {"suppliers": len(items), "out_of_range": out_of_range}
