<file path="test_validators_later.py">
"""Tests for V7-V9 in validators_later.py. Run from the repository root with ``python -m unittest``."""
import unittest

from validators_later import V7, V8, V9


class TestV7(unittest.TestCase):
    def test_passes_when_within_capacity(self):
        result = V7().run([{"wh": "A", "capacity": 10, "max_units": 10}])
        self.assertTrue(result.passed)

    def test_fails_when_over_capacity_and_names_warehouse(self):
        result = V7().run([{"wh": "A", "capacity": 10, "max_units": 11}])
        self.assertFalse(result.passed)
        self.assertEqual(result.measured["over_capacity"][0]["wh"], "A")

    def test_empty_input_fails(self):
        self.assertEqual(V7().run([]).reason, "failed: empty input")


class TestV8(unittest.TestCase):
    def test_passes_when_every_expiry_notified(self):
        entry = {
            "expired": [["milk", "A", 3]],
            "notified": [["milk", "A", 3], ["eggs", "B", 1]],
        }
        self.assertTrue(V8().run([entry]).passed)

    def test_no_expiries_passes(self):
        entry = {"expired": [], "notified": []}
        self.assertTrue(V8().run([entry]).passed)

    def test_fails_when_expiry_not_notified(self):
        entry = {"expired": [["milk", "A", 3]], "notified": []}
        result = V8().run([entry])
        self.assertFalse(result.passed)
        self.assertEqual(result.measured["unnotified"], [["milk", "A", 3]])

    def test_quantity_must_match(self):
        entry = {"expired": [["milk", "A", 3]], "notified": [["milk", "A", 2]]}
        self.assertFalse(V8().run([entry]).passed)

    def test_duplicate_expiries_need_duplicate_notifications(self):
        entry = {"expired": [["milk", "A", 3], ["milk", "A", 3]], "notified": [["milk", "A", 3]]}
        result = V8().run([entry])
        self.assertFalse(result.passed)
        self.assertEqual(len(result.measured["unnotified"]), 1)

    def test_empty_input_fails(self):
        self.assertEqual(V8().run([]).reason, "failed: empty input")


class TestV9(unittest.TestCase):
    def test_passes_within_range_and_at_bounds(self):
        entries = [
            {"supplier": "S1", "reliability": 0},
            {"supplier": "S2", "reliability": 50},
            {"supplier": "S3", "reliability": 100},
        ]
        self.assertTrue(V9().run(entries).passed)

    def test_fails_below_and_above_range(self):
        entries = [
            {"supplier": "S1", "reliability": -1},
            {"supplier": "S2", "reliability": 101},
        ]
        result = V9().run(entries)
        self.assertFalse(result.passed)
        self.assertEqual(
            [e["supplier"] for e in result.measured["out_of_range"]], ["S1", "S2"]
        )

    def test_empty_input_fails(self):
        self.assertEqual(V9().run([]).reason, "failed: empty input")


if __name__ == "__main__":
    unittest.main()
</file>

<notes>
- Spec gives no bounds for reliability. I assumed an inclusive 0–100 range, set as `RELIABILITY_MIN`/`RELIABILITY_MAX` at the top of `validators_later.py`. Please confirm or correct these.
- V7 treats "respected" as `max_units <= capacity`, with equality passing.
- V8 matches expiries to notifications on the full `[sku, wh, qty]` triple, counting multiplicity. A notification with a different quantity does not count as notifying the expiry. Notifications with no matching expiry are ignored.
- All three validators use `name = "entries"`, as the spec gives.
- The test file is named `test_validators_later.py` and sits at the repo root, since I could not see an existing test layout. It runs with `python -m unittest` from the root. Move it if the repo keeps tests elsewhere.
- I did not run the tests.
</notes>
